mt19937 rng((unsigned long long) new char);

int rnd_l(int l,int r){
	return rng()%(r-l+1)+l;
}

char rnd(vector<int> v){ // 0~25 权重 
	int sum=0;
	for (auto u : v) sum+=u;
	int r=rng()%(sum)+1,c=0;
	sum=0;
	for (auto u : v){
		if (sum+u>=r) return c+'a';
		c++;
		sum+=u;
	}
}

vector<int> pl;

void rnd_g(){
